    explanation: `施工体制台帳は、下請・孫請など工事施工を請け負うすべての業者名、各業者の施工範囲、技術者名などを記載した台帳で、作成義務を負うのは元請負人である。建設業法では、特定建設業者が発注者から直接請け負った建設工事を施工するために締結した下請契約の総額が政令で定める金額以上となる場合に作成が義務付けられ、公共工事では入契法により下請契約の金額にかかわらず作成が必要である。下請負人は自らが締結した再下請契約の内容を元請負人に通知する再下請負通知の義務を負う。台帳は工事現場ごとに備え置き、発注者から請求があれば閲覧に供する。

【図解】施工体制台帳の役割分担
主体｜義務
元請負人｜台帳の作成・現場備置き・施工体系図の掲示
下請負人｜再下請負通知書の提出
発注者｜請求により台帳を閲覧できる`,
