    correctKey: 'A',
    explanation: `無線局を開設しようとする者は、電波法第4条により、原則として総務大臣の免許を受けなければならない。免許申請を受けた総務大臣は、周波数割当ての可能性など法定の事項を審査し、適合していると認めるときは、工事落成の期限、電波の型式および周波数、識別信号、空中線電力、運用許容時間を指定して予備免許を与える。申請者は工事が落成したときは落成後の検査を受け、これに合格すると免許が付与され、免許状が交付される。免許を受けた後でなければ無線局を運用してはならない。

【図解】無線局免許の流れ
・免許申請→総務大臣が審査
・予備免許→工事落成期限・周波数等を指定
・工事落成→落成後の検査を受検
・検査合格→免許付与・免許状交付→運用開始`,
    difficulty: 'basic',
