    correctKey: 'A',
    explanation: `工程管理は、計画（Plan)を立て、実施（Do）し、実施状況を計画と比較検討（Check）し、遅れがあれば作業改善や工程促進の処置（Act）を行うという管理サイクルを工事期間中繰り返すものである。進捗の確認を完成時に一度だけ行うのでは、遅れの発見が手遅れとなり是正の機会を失うため、フォローアップは日々または定期的に行い、状況の変化に応じて計画自体の修正も行う。実施工程と計画工程の比較には工程曲線やネットワーク工程表を用い、差異の原因を分析して、作業方法の改善、配員の増強、作業順序の変更などの処置を講じる。

【図解】工程管理のPDCA
段階｜内容
Plan｜工程計画の作成
Do｜工事の実施
Check｜進捗の測定と計画との比較
Act｜遅れの原因分析と是正処置`,
