    question: '山崩しに関する記述として、最も適当なものはどれか。',
    choices: [
      { key: 'A', text: '山崩しは、工期を短縮するためにクリティカルパス上の作業を圧縮することである。', explanation: '誤り。正しくは工期短縮はクラッシングであり、山崩しは資源の平準化が目的である。' },
      { key: 'B', text: '山崩しでは、クリティカルパス上の作業の開始時期を優先的に移動する。', explanation: '誤り。正しくは余裕のない作業は動かせず、フロートのある作業を移動する。' },
      { key: 'C', text: '山崩しは、作業の余裕日数を利用して作業時期をずらし、日々の資源所要量を平準化することである。', explanation: '正しい。フロートの範囲内で作業を移動し、山を低くならして需要を平準化する。' },
      { key: 'D', text: '山崩しを行うと、必ず工期が延長される。', explanation: '誤り。正しくはフロートの範囲内で行う限り工期は変わらない。' },
    ],
    correctKey: 'C',
    explanation: `山崩しは、山積み図で把握した資源需要の山（ピーク）を低くならし、日々の作業員数や機械台数を平準化する操作である。具体的には、余裕日数（フロート）を持つ非クリティカル作業の開始時期をフロートの範囲内で移動させ、需要の集中を避ける。クリティカルパス上の作業は余裕がないため動かすことができず、これを動かすと工期が延びてしまう。平準化により、日々の労務者数の変動が小さくなり、雇用の安定、仮設規模の縮小、経済的な施工が可能となる。工期短縮を目的とするクラッシングとは目的が異なる点に注意する。

【図解】山崩しの原則
・移動できる作業→フロートを持つ非クリティカル作業
・移動の範囲→フロートの範囲内（工期に影響させない）
・動かせない作業→クリティカルパス上の作業
・目的→資源需要の平準化（工期短縮ではない）`,
