    correctKey: 'B',
    explanation: `出来高累計曲線は、縦軸に出来高（金額または比率）の累計、横軸に工期をとって工事の進捗を表すもので、一般にS字形（Sカーブ）となる。これは、工事初期には仮設・準備作業が中心で出来高が上がりにくく、中期には主要工事が最盛期を迎えて出来高が急増し、終期には検査・手直し・後片付けなどで再び伸びが鈍るためである。したがって全期間直線的に出来高が伸びることは通常なく、直線を理想とする考えは誤りである。進度管理では計画Sカーブと実績を重ねて比較し、差異が大きい場合は原因を分析して対策を講じる。

【図解】Sカーブの形の理由
時期｜工事内容｜出来高の伸び
初期｜準備・仮設工事｜小さい
中期｜主体工事の最盛期｜大きい
終期｜試験・検査・手直し｜小さい`,
