    explanation: `LAN配線の認証試験には、パーマネントリンク試験とチャネル試験の2つの構成がある。パーマネントリンクは、配線盤から通信アウトレットまでの固定配線部分（工事業者が施工する区間）を対象とし、施工品質の確認に用いる。チャネルは、機器コード・パッチコードを含む端末機器間の伝送路全体を対象とし、システムとしての運用時性能の確認に用いる。したがって、機器コードを含む全体を対象とするのはチャネル試験であり、Aの記述はパーマネントリンクの説明として誤りである。測定では事前のリファレンス設定を行い、規格限界値による自動合否判定の結果を試験成績書として保存することが基本である。

【図解】リンクとチャネルの違い
構成｜範囲｜目的
パーマネントリンク｜固定配線部分のみ｜施工品質の確認
チャネル｜機器コードを含む全体｜運用時性能の確認`,
