    explanation: `カテゴリ6Aは、伝送帯域500MHzまでの伝送特性を規定したツイストペアケーブル配線の性能区分であり、10GBASE-T（10ギガビットイーサネット）を最大100mのチャネル（固定配線90m＋機器コード等10m）で支援できる。10Gのような高速伝送では、同一ケーブル内の対間漏話だけでなく、束ねて敷設された隣接ケーブルから漏れ込むエイリアンクロストークが問題となるため、カテゴリ6Aではその特性も規定されており、施工時には過度の結束を避けるなどの配慮が必要である。試験ではカテゴリ5e（100MHz）、6（250MHz）、6A（500MHz）の帯域と対応イーサネット規格の組合せが問われる。

【図解】カテゴリと帯域の対応
カテゴリ｜規定帯域｜代表的な対応規格
5e｜100MHz｜1000BASE-T
6｜250MHz｜1000BASE-T（余裕あり）
6A｜500MHz｜10GBASE-T（100m）`,
