    correctKey: 'A',
    explanation: `WBGT値は、日射の有無により計算式が異なる。

式（屋外で日射のある場合）：WBGT＝0.7×自然湿球温度＋0.2×黒球温度＋0.1×乾球温度
代入：WBGT＝0.7×25＋0.2×40＋0.1×30
＝17.5＋8＋3
＝28.5度
答え：WBGT値は28.5度である。

日射のない場合（屋内など）は、WBGT＝0.7×自然湿球温度＋0.3×黒球温度で計算し、乾球温度は使用しない。本問の値を日射なしの式に入れると0.7×25＋0.3×40＝29.5度となるが、屋外で日射がある条件なので誤りである。係数0.7、0.2、0.1（日射なしは0.7、0.3）は確実に覚えておく。

【図解】WBGT計算式の使い分け
条件｜計算式
屋外・日射あり｜0.7×湿球＋0.2×黒球＋0.1×乾球
屋内・日射なし｜0.7×湿球＋0.3×黒球`,
    difficulty: 'advanced',
