    explanation: `建設業法では、建設業を営もうとする者は、政令で定める軽微な建設工事のみを請け負う場合を除き、建設工事の種類（29業種）ごとに建設業の許可を受けなければならないとされている。軽微な建設工事とは、建築一式工事では請負代金1,500万円未満または延べ面積150平方メートル未満の木造住宅の工事、建築一式工事以外の工事（電気通信工事を含む）では請負代金500万円未満の工事をいう。許可は業種ごとであるため、電気通信工事業の許可で電気工事など他業種の工事を請け負うことはできない（附帯工事を除く）。許可には一般建設業と特定建設業の区分がある。

【図解】許可が不要な軽微な建設工事
工事の種類｜基準
建築一式工事｜1,500万円未満または木造住宅150平方メートル未満
その他の工事（電気通信等）｜500万円未満
※金額は消費税込み・注文者支給材料の価格も考慮される`,
