    correctKey: 'C',
    explanation: `現場代理人は、請負人の代理人として工事現場の運営・取締りを行う者であり、その設置は建設業法上の義務ではなく、公共工事標準請負契約約款などの契約に基づいて置かれる。建設業法第19条の2は、請負人が現場代理人を置く場合には、その現場代理人の権限に関する事項および現場代理人の行為についての注文者の請負人に対する意見の申出の方法を、書面により注文者に通知しなければならないと定めている。同様に、注文者が監督員を置く場合にも請負人への通知義務がある。現場代理人は、主任技術者・監理技術者や専門技術者と兼ねることができる。公共工事では現場代理人は原則現場常駐とされるが、契約により常駐緩和が認められる場合がある。

【図解】現場代理人の要点
項目｜内容
設置根拠｜契約（約款）による（法律上の義務ではない）
選任者｜請負人
通知義務｜権限等を書面で注文者へ通知
兼任｜主任技術者・監理技術者と兼任可能`,
