    question: '電気通信事業法における「電気通信事業」の定義に関する記述として、正しいものはどれか。',
    choices: [
      { key: 'A', text: '電気通信事業とは、電気通信役務を他人の需要に応ずるために提供する事業（放送法に規定する一定のものを除く）をいう。', explanation: '正しい。他人の需要に応じた役務提供が事業の要件である。' },
      { key: 'B', text: '電気通信事業とは、自己の業務のためにのみ通信設備を運用することをいう。', explanation: '誤り。正しくは自己使用は事業に該当せず、他人への役務提供が要件である。' },
      { key: 'C', text: '電気通信事業とは、通信機器を製造販売する事業をいう。', explanation: '誤り。正しくは機器の製造販売は電気通信役務の提供ではない。' },
      { key: 'D', text: '電気通信事業とは、放送番組を制作する事業をいう。', explanation: '誤り。正しくは放送番組制作は電気通信役務の提供ではない。' },
    ],
    correctKey: 'A',
    explanation: `電気通信事業法において、電気通信事業とは、電気通信役務を他人の需要に応ずるために提供する事業（放送法に規定する放送局設備供給役務に係る事業を除く）をいう。ここで電気通信役務とは、電気通信設備を用いて他人の通信を媒介し、その他電気通信設備を他人の通信の用に供することをいう。自社の業務のためにのみ電気通信設備を用いる場合（自営通信）は、他人の需要に応じた役務提供ではないため電気通信事業に該当しない。電気通信事業を営もうとする者は、その内容に応じて総務大臣の登録を受け、または総務大臣への届出を行う必要がある。

【図解】電気通信事業の判定
要素｜内容
役務の内容｜電気通信役務（他人の通信の媒介等）
提供の相手｜他人の需要に応ずる
除外｜自己使用の通信・放送局設備供給役務に係る事業
参入手続き｜登録または届出`,
    difficulty: 'basic',
