    correctKey: 'D',
    explanation: `電気通信事業法第2条において、電気通信役務とは、電気通信設備を用いて他人の通信を媒介し、その他電気通信設備を他人の通信の用に供することをいうと定義されている。他人の通信の媒介とは、他人の依頼を受けて、情報をその内容を変更することなく伝送・交換し、隔地者間の通信を取り次ぐことをいう。電話サービスやインターネット接続サービスの提供はその典型である。また、通信の媒介までは行わなくても、電気通信設備を他人の通信の用に供すること（回線の貸与等）も役務に含まれる。この役務を他人の需要に応ずるために提供する事業が電気通信事業であり、参入には登録または届出を要する。

【図解】電気通信役務の構成
要素｜内容
他人の通信の媒介｜依頼を受け内容を変えずに通信を取り次ぐ
設備を他人の通信の用に供する｜回線・設備の提供等
提供の形態｜他人の需要に応ずる提供→電気通信事業`,
