    correctKey: 'A',
    explanation: `労働安全衛生法第88条第1項ただし書により、労働安全衛生マネジメントシステム（OSHMS）を適切に実施しており、危険性・有害性の調査（リスクアセスメント）とその結果に基づく措置など、厚生労働省令で定める要件を満たすものとして労働基準監督署長の認定を受けた事業者については、機械等の設置・移転・主要構造部分の変更に係る計画の届出義務が免除される。これは、自主的な安全衛生管理が高い水準で行われている事業場に対し、手続きの負担を軽減しつつ自主管理を促進する趣旨である。認定を受けても、設置する機械等を法令の基準に適合させる義務や、その他の安全衛生管理の義務がなくなるわけではない。

【図解】計画届免除認定
項目｜内容
根拠｜法第88条第1項ただし書
要件｜OSHMSの適切な実施・リスクアセスメントの実施等
認定者｜労働基準監督署長
効果｜設置等の計画届出義務の免除（管理義務は継続）`,
