    explanation: `労働安全衛生法第88条は、建設業の仕事の計画の届出について、規模・危険性に応じた二段階の制度を設けている。高さが300m以上の塔の建設の仕事、堤高150m以上のダムの建設の仕事、最大支間500m以上の橋梁の建設の仕事、長さ3,000m以上のずい道等の建設の仕事など、特に大規模なものは、仕事の開始の日の30日前までに厚生労働大臣に届け出る。また、高さ31mを超える建築物の建設等の仕事、ずい道等の建設の仕事、掘削の高さまたは深さが10m以上の地山の掘削の作業を行う仕事など一定のものは、仕事の開始の日の14日前までに所轄労働基準監督署長に届け出る。通信鉄塔の建設工事も高さによってはこれらの届出対象となる。

【図解】仕事の届出の二段階
届出先｜期限｜対象の例
厚生労働大臣｜開始30日前｜高さ300m以上の塔・長大ずい道等
労働基準監督署長｜開始14日前｜高さ31m超の建築物・10m以上の掘削等`,
    difficulty: 'advanced',
