    correctKey: 'D',
    explanation: `労働安全衛生法第60条により、建設業その他政令で定める業種の事業者は、新たに職務に就くこととなった職長その他の作業中の労働者を直接指導または監督する者（作業主任者を除く）に対し、安全または衛生のための教育を行わなければならない。教育事項は、作業方法の決定および労働者の配置に関すること、労働者に対する指導または監督の方法に関すること、危険性または有害性等の調査（リスクアセスメント）およびその結果に基づき講ずる措置に関すること、異常時等における措置に関すること、その他現場監督者として行うべき労働災害防止活動に関することである。現場の第一線監督者の能力向上が労働災害防止の要であることから設けられた制度である。

【図解】職長等教育の要点
項目｜内容
対象者｜新たに職長等となる者（作業主任者を除く）
対象業種｜建設業・製造業の一部等の政令業種
教育事項｜作業方法・配置・指導監督・リスクアセスメント等
実施者｜事業者`,
