    correctKey: 'D',
    explanation: `電気工事士法は、電気工事の作業に従事する者の資格および義務を定め、電気工事の欠陥による災害の発生を防止することを目的とする法律であり、その対象は、一般用電気工作物等（住宅・小規模店舗等の設備）および自家用電気工作物のうち最大電力500kW未満の需要設備の電気工事である。第一種電気工事士は両方の工事に、第二種電気工事士は一般用電気工作物等の工事に従事できる。500kW以上の需要設備は、専門技術者による自主保安体制が期待できるため同法の対象外である。電気通信設備そのものの工事（通信ケーブルの敷設等）は原則として電気工事に該当しないが、通信機器への電源供給設備（分電盤からのコンセント増設等）の工事は電気工事に該当し、資格が必要である。

【図解】電気工事士法の対象
区分｜資格
一般用電気工作物等｜第一種・第二種電気工事士
自家用（500kW未満の需要設備）｜第一種電気工事士等
500kW以上の需要設備｜法の対象外（自主保安）
通信設備自体の工事｜原則対象外`,
