【図解】自家用電気工作物の工事資格
工事の範囲｜必要資格
自家用の工事全般（500kW未満）｜第一種電気工事士
自家用の600V以下の簡易電気工事｜認定電気工事従事者でも可
ネオン・非常用予備発電装置｜特種電気工事資格者
