    correctKey: 'A',
    explanation: `個人情報保護法において、個人情報とは、生存する個人に関する情報であって、当該情報に含まれる氏名、生年月日その他の記述等により特定の個人を識別することができるもの（他の情報と容易に照合することができ、それにより特定の個人を識別することができることとなるものを含む）、または個人識別符号（DNA・顔認証データ等の身体的特徴を変換した符号や、マイナンバー・免許証番号等の個人に割り当てられた符号）が含まれるものをいう。工事関係でも、作業員名簿、入退場記録、監視カメラの映像などは個人情報に該当し得るため、施工管理においても適正な取扱いが求められる。

【図解】個人情報の定義の構造
要素｜内容
主体｜生存する個人に関する情報
識別性｜氏名等で特定個人を識別できる
照合容易性｜他の情報と容易に照合して識別できるものを含む
個人識別符号｜顔認証データ・免許証番号・マイナンバー等`,
