    correctKey: 'C',
    explanation: `個人情報取扱事業者は、個人情報を取り扱うにあたっては、その利用の目的をできる限り特定しなければならず、あらかじめ本人の同意を得ないで、特定された利用目的の達成に必要な範囲を超えて個人情報を取り扱ってはならない（目的外利用の制限）。また、個人情報を取得した場合は、あらかじめその利用目的を公表している場合を除き、速やかに利用目的を本人に通知し、または公表しなければならない。偽りその他不正の手段による取得も禁止される。現在は取り扱う個人情報の件数にかかわらず、個人情報データベース等を事業の用に供している者は個人情報取扱事業者として法の適用を受けるため、建設業者・工事業者も例外ではない。

【図解】利用目的に関する義務
場面｜義務
取扱い開始前｜利用目的をできる限り特定
取得時｜利用目的の通知または公表
利用時｜目的達成に必要な範囲内（目的外は本人同意）
取得方法｜不正の手段による取得の禁止`,
