    correctKey: 'D',
    explanation: `サイバーセキュリティ基本法において、サイバーセキュリティとは、電子的方式、磁気的方式その他人の知覚によっては認識することができない方式により記録され、または発信され、伝送され、もしくは受信される情報の漏えい、滅失または毀損の防止その他の当該情報の安全管理のために必要な措置、ならびに情報システムおよび情報通信ネットワークの安全性および信頼性の確保のために必要な措置が講じられ、その状態が適切に維持管理されていることをいう。同法は、国・地方公共団体の責務のほか、電気通信事業者を含む重要社会基盤事業者（重要インフラ事業者）が、サービスを安定的かつ適切に提供するため、サイバーセキュリティの確保に自主的かつ積極的に努めることを求めている。

【図解】サイバーセキュリティの構成
要素｜内容
情報の安全管理｜漏えい・滅失・毀損の防止等
システムの確保｜情報システム・ネットワークの安全性・信頼性
状態の維持｜措置が講じられた状態の維持管理
事業者の位置づけ｜重要社会基盤事業者の自主的な取組み`,
